#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    for (int i = 0; i < n; i++) {
        while (a[i] >= 1 && a[i] <= n && a[a[i] - 1] != a[i]) {
            swap(a[i], a[a[i] - 1]);
        }
    }
    long long answer = n + 1;
    for (int i = 0; i < n; i++) {
        if (a[i] != i + 1) {
            answer = i + 1;
            break;
        }
    }
    cout << answer << "\n";

    return 0;
}

